import io
import numpy as np
import pandas as pd

def solve(data):
    from openpyxl import Workbook
    wb=Workbook(); sheet=wb.active
    for row in data['excel_rows']: sheet.append(row)
    output=io.BytesIO(); wb.save(output); output.seek(0)
    return pd.read_excel(output).to_dict(orient='records')

